function legacy_syncjob_custom_params_ok(string $custom_params, array $whitelist): bool
{
    $GLOBALS['IMAPSYNC_OPTIONS']['whitelist'] = $whitelist;
    $_SESSION['return'] = [];
    // PHP 8 warns on $param[0] for an empty option name; legacy runs with warnings hidden.
    set_error_handler(static fn (): bool => true);

    try {
        return (static function (string $custom_params): bool {
            $_action = $_type = $_data_log = $_attr = null;

          // validate custom params
          foreach (explode('-', $custom_params) as $param){
            if(empty($param)) continue;

            // extract option
            if (str_contains($param, '=')) $param = explode('=', $param)[0];
            else $param = rtrim($param, ' ');
            // remove first char if first char is -
            if ($param[0] == '-') $param = ltrim($param, $param[0]);

            if (str_contains($param, ' ')) {
              // bad char
              $_SESSION['return'][] = array(
                'type' => 'danger',
                'log' => array(__FUNCTION__, $_action, $_type, $_data_log, $_attr),
                'msg' => 'bad character SPACE'
              );
              return false;
            }

            // check if param is whitelisted
            if (!in_array(strtolower($param), $GLOBALS["IMAPSYNC_OPTIONS"]["whitelist"])){
              // bad option
              $_SESSION['return'][] = array(
                'type' => 'danger',
                'log' => array(__FUNCTION__, $_action, $_type, $_data_log, $_attr),
                'msg' => 'bad option '. $param
              );
              return false;
            }
          }

            return true;
        })($custom_params);
    } finally {
        restore_error_handler();
    }
}

function legacy_syncjob_is_valid_domain_name($domain_name, $options = array()) {
  if (empty($domain_name)) {
    return false;
  }

  // Convert domain name to ASCII for validation
  $domain_name = idn_to_ascii($domain_name, 0, INTL_IDNA_VARIANT_UTS46);

  if (isset($options['allow_wildcard']) && $options['allow_wildcard'] == true) {
    // Remove '*.' if wildcard subdomains are allowed
    if (strpos($domain_name, '*.') === 0) {
      $domain_name = substr($domain_name, 2);
    }
  }

  return (preg_match("/^([a-z\d](-*[a-z\d])*)(\.([a-z\d](-*[a-z\d])*))*$/i", $domain_name)
       && preg_match("/^.{1,253}$/", $domain_name)
       && preg_match("/^[^\.]{1,63}(\.[^\.]{1,63})*$/", $domain_name));
}
